  ASSERT_FLOAT_EQ(0, YGNodeLayoutGetWidth(root_child6));
  ASSERT_FLOAT_EQ(0, YGNodeLayoutGetHeight(root_child6));

  ASSERT_FLOAT_EQ(40, YGNodeLayoutGetLeft(root_child7));
  ASSERT_FLOAT_EQ(40, YGNodeLayoutGetTop(root_child7));
