  ASSERT_FLOAT_EQ(80, YGNodeLayoutGetLeft(root_child5));
  ASSERT_FLOAT_EQ(40, YGNodeLayoutGetTop(root_child5));
  ASSERT_FLOAT_EQ(40, YGNodeLayoutGetWidth(root_child5));
