  ASSERT_FLOAT_EQ(40, YGNodeLayoutGetTop(root_child8));
  ASSERT_FLOAT_EQ(40, YGNodeLayoutGetWidth(root_child8));
  ASSERT_FLOAT_EQ(40, YGNodeLayoutGetHeight(root_child8));

  YGNodeFreeRecursive(root);

  YGConfigFree(config);
